const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const states={'11':['RO','Rondônia'],'12':['AC','Acre'],'13':['AM','Amazonas'],'14':['RR','Roraima'],'15':['PA','Pará'],'16':['AP','Amapá'],'17':['TO','Tocantins'],'21':['MA','Maranhão'],'22':['PI','Piauí'],'23':['CE','Ceará'],'24':['RN','Rio Grande do Norte'],'25':['PB','Paraíba'],'26':['PE','Pernambuco'],'27':['AL','Alagoas'],'28':['SE','Sergipe'],'29':['BA','Bahia'],'31':['MG','Minas Gerais'],'32':['ES','Espírito Santo'],'33':['RJ','Rio de Janeiro'],'35':['SP','São Paulo'],'41':['PR','Paraná'],'42':['SC','Santa Catarina'],'43':['RS','Rio Grande do Sul'],'50':['MS','Mato Grosso do Sul'],'51':['MT','Mato Grosso'],'52':['GO','Goiás'],'53':['DF','Distrito Federal']};
const featured={'13':'Pitinga · estanho, nióbio e tântalo','15':'Carajás · ferro e cobre','29':'Santa Maria Eterna · sílica','31':'Araxá · nióbio e terras raras','52':'Minaçu · terras raras'};
export const project=([lng,lat])=>[(lng+75)*13.6+14,(6-lat)*13.6+4];
async function drawMap(){try{const data=await fetch('assets/brazil-states.geojson').then(r=>{if(!r.ok)throw Error('map');return r.json()});const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 600 570');svg.setAttribute('role','group');svg.setAttribute('aria-label','Estados brasileiros. Use Tab e Enter para explorar.');svg.innerHTML='<defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#8da080" stroke-opacity=".09" stroke-width=".5"/></pattern></defs><rect width="600" height="570" fill="url(#grid)"/>';
for(const f of data.features){const id=String(f.properties.codarea);const s=states[id]||[id,id];const polys=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];const path=document.createElementNS(ns,'path');path.setAttribute('d',polys.map(p=>p.map(r=>r.map((c,i)=>(i?'L':'M')+project(c).map(n=>n.toFixed(2)).join(',')).join(' ')+'Z').join(' ')).join(' '));path.classList.add('state');path.setAttribute('tabindex','0');path.setAttribute('role','button');path.setAttribute('aria-label',s[1]+(featured[id]?' — '+featured[id]:''));path.dataset.state=id;const activate=()=>{$$('.state').forEach(p=>p.classList.remove('selected'));path.classList.add('selected');$('#map-readout').innerHTML=`<span class="tiny-label">${s[0]} / BRASIL</span><strong>${s[1]}</strong><span>${featured[id]||'Explore os dados nacionais nos capítulos abaixo.'}</span>`};path.addEventListener('click',activate);path.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}});svg.append(path)}
const labels=[['AM',-64,-4],['PA',-53,-4],['BA',-42,-12],['MG',-45,-18],['GO',-50,-15],['MT',-57,-13],['RS',-54,-29],['SP',-49,-23]];for(const [s,lng,lat]of labels){const[x,y]=project([lng,lat]);svg.insertAdjacentHTML('beforeend',`<text x="${x}" y="${y}" class="map-label">${s}</text>`)}$('#hero-map').append(svg);document.dispatchEvent(new Event('atlas-map-ready'))}catch{$('#hero-map').innerHTML='<p class="note">Mapa indisponível. Os dados e a lista de projetos continuam acessíveis abaixo.</p>'}}
function reeChart(mode='reserve'){const rows=mode==='reserve'?[['China',44],['Brasil',21],['Austrália',6.3],['Estados Unidos',1.9]]:[['China',270000],['Estados Unidos',51000],['Austrália',29000],['Brasil',2000]];const max=rows[0][1];$('#ree-chart').innerHTML=rows.map(([name,value])=>`<div class="bar-row ${name==='Brasil'?'featured':''}"><div class="bar-label"><span>${name}</span><strong>${value.toLocaleString('pt-BR')}${mode==='reserve'?' Mt':' t'}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${value/max*100}%"></div></div></div>`).join('');$('#ree-caption').textContent=mode==='reserve'?'Reservas · milhões de toneladas de REO · USGS 2026, estimativa histórica anterior à revisão de maio. A escala dos gráficos começa em zero.':'Produção mineral estimada de 2025 · toneladas de REO · USGS 2026. Brasil: aproximadamente 0,5% do total mundial de 390 mil t.';$$('[data-ree]').forEach(b=>{b.classList.toggle('active',b.dataset.ree===mode);b.setAttribute('aria-pressed',String(b.dataset.ree===mode))})}
$$('[data-ree]').forEach(b=>b.addEventListener('click',()=>reeChart(b.dataset.ree)));reeChart();drawMap();window.addEventListener('scroll',()=>{$('#reading-progress').style.width=(scrollY/(document.documentElement.scrollHeight-innerHeight)*100)+'%'},{passive:true});$('.dialog-close').addEventListener('click',()=>$('#mineral-dialog').close());$('#mineral-dialog').addEventListener('click',e=>{if(e.target===$('#mineral-dialog'))$('#mineral-dialog').close()});
